     "html": "En un aula de 37 alumnos, cada alumno ha hecho el experimento 50 veces, de modo que se ha lanzado la moneda 1.850 veces. El suceso <math display=\"inline\"><mi>S</mi></math> ha ocurrido 611 veces. Se obtiene así:"
