         "html": "En una casa hay tres llaveros <math display=\"inline\"><mi>A</mi></math>, <math display=\"inline\"><mi>B</mi></math> y <math display=\"inline\"><mi>C</mi></math>. En el primero hay 5 llaves, en el segundo 7 y en el tercero 8. En cada llavero, una única llave abre la puerta de la calle. Se elige un llavero al azar y se saca de él una llave (cualquiera) para abrir la puerta de la calle."
