         "html": "<math display=\"inline\"><mrow><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><mi>C</mi><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> eta BAI</mtext></mrow><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mo>=</mo><mfrac><mn>1</mn><mn>3</mn></mfrac><mo>⋅</mo><mfrac><mn>1</mn><mn>8</mn></mfrac><mo>=</mo><mfrac><mn>1</mn><mn>24</mn></mfrac><mo>=</mo><mfrac><mn>35</mn><mn>840</mn></mfrac></mrow></math>"
