     "mota": "testua",
     "html": "Resolveremos este caso siguiendo el sentido común. De 840 intentos, en 131 se elige la llave correcta. Y de ellos 56 corresponden al llavero <math display=\"inline\"><mi>A</mi></math>, 40 al <math display=\"inline\"><mi>B</mi></math> y 35 al <math display=\"inline\"><mi>C</mi></math>."
