     "html": "Sabiendo que hemos elegido la llave correcta, la probabilidad de que sea del llavero <math display=\"inline\"><mi>A</mi></math> será, por tanto, <math display=\"inline\"><mfrac><mn>56</mn><mn>131</mn></mfrac></math>."
