     "mota": "zentratua",
     "blokeak": [
      {
       "mota": "testua",
       "html": "<math display=\"block\"><mrow><mi>P</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><mfrac><mi>B</mi><mrow><mn>2</mn><mspace width=\"0.222em\"></mspace><mi>b</mi><mi>e</mi><mi>l</mi><mi>t</mi><mi>z</mi></mrow></mfrac><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mo>=</mo><mi>P</mi><mfrac><mrow><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>B</mi><mspace width=\"0.222em\"></mspace><mi>e</mi><mi>t</mi><mi>a</mi><mspace width=\"0.222em\"></mspace><mn>2</mn><mspace width=\"0.222em\"></mspace><mi>b</mi><mi>e</mi><mi>l</mi><mi>t</mi><mi>z</mi><mo stretchy=\"false\" form=\"postfix\">]</mo></mrow><mi>P</mi></mfrac><mo stretchy=\"false\" form=\"prefix\">[</mo><mn>2</mn><mspace width=\"0.222em\"></mspace><mi>b</mi><mi>e</mi><mi>l</mi><mi>t</mi><mi>z</mi><mo stretchy=\"false\" form=\"postfix\">]</mo></mrow></math>"
      }
     ]
