       "html": "Hemos tomado familias de tres hijos y hemos analizado la distribución de sexos. Por ejemplo, si escribimos (M,N,N), significa que el mayor es chico y los otros dos chicas. ¿Cuántos elementos tiene el espacio muestral <math display=\"inline\"><mi>E</mi></math>? Describir los sucesos siguientes: <math display=\"inline\"><mrow><mi>A</mi><mo>=</mo></mrow></math>  &quot;La menor es chica&quot;, <math display=\"inline\"><mrow><mi>B</mi><mo>=</mo></mrow></math>  &quot;El mayor es chico&quot;. ¿Qué es <math display=\"inline\"><mrow><mi>A</mi><mo>∪</mo><mi>B</mi></mrow></math>?"
