     "mota": "testua",
     "html": "<strong>Enunciado (en inglés):</strong> «Suppose that the blood test for some disease is reliable... for people who are infected the test produces a positive result in 99&#x27;99% of cases; for people not infected a positive test result is obtained only in 0&#x27;02% of cases... one person in 10.000 people is infected. A person is selected at random and found to test positive. What is the probability that the individual is actually infected?»"
