     "mota": "testua",
     "html": "Es más fácil calcular primero la probabilidad de que nadie <strong>comparta</strong> cumpleaños, <math display=\"inline\"><mi>p</mi></math>. <math display=\"inline\"><mi>k</mi></math> personas señalan cada una uno de los 365 días del año; todos los resultados posibles son <math display=\"inline\"><msup><mn>365</mn><mi>k</mi></msup></math> (muestreo <strong>con reposición</strong>). Para que no coincidan dos, el número de opciones es una variación (<strong>sin reposición</strong>), <math display=\"inline\"><mrow><mn>365</mn><mi>!</mi><mi>/</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>365</mn><mo>−</mo><mi>k</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mi>!</mi></mrow></math>. Por tanto la probabilidad de que todos los cumpleaños sean distintos y, por la regla del complementario, la de que dos o más personas coincidan: <math display=\"block\"><mrow><mi>p</mi><mo>=</mo><mfrac><mrow><mn>365</mn><mi>!</mi></mrow><mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>365</mn><mo>−</mo><mi>k</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mi>!</mi><mo>⋅</mo><msup><mn>365</mn><mi>k</mi></msup></mrow></mfrac><mo>,</mo><mspace width=\"1.0em\"></mspace><mi>q</mi><mo>=</mo><mn>1</mn><mo>−</mo><mi>p</mi><mi>.</mi></mrow></math> Por la aproximación de Stirling, sustituyendo <math display=\"inline\"><mrow><mi>n</mi><mi>!</mi><mo>≈</mo><msqrt><mrow><mn>2</mn><mi>π</mi><mi>n</mi></mrow></msqrt><msup><mi>n</mi><mi>n</mi></msup><msup><mi>e</mi><mrow><mi>−</mi><mi>n</mi></mrow></msup></mrow></math>, <math display=\"inline\"><mrow><mn>365</mn><mi>!</mi></mrow></math> y <math display=\"inline\"><mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>365</mn><mo>−</mo><mi>k</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mi>!</mi></mrow></math> y simplificando (el cociente de las raíces da el exponente <math display=\"inline\"><mrow><mi>+</mi><mn>1</mn><mi>/</mi><mn>2</mn></mrow></math>):"
