     "xehetasuna": "CAx, páginas 10-11 (unidad 0007, hoja doble; #CAxp10/#CAxp11): cinco ejercicios, de los más limpios de todo el lote. (1) Lotería del Reino Unido (hipergeométrica, N=49, M=6, n=6): Pr(k)=C(6,k)C(43,6-k)/C(49,6), siete probabilidades de 1/2,29 ... 1/(13,98 millones), suma 1. (2) Poisson en mensajes (lambda=2): Pr(x)=2^x/x! e^(-2) = 0,135/0,271/0,271/0,180/0,090 (Pr(1)=Pr(2)). (3) aproximación de Poisson de la binomial (bombillas, Bin(200,0.005), lambda=1): Pr=0,37/0,37/0,18 (binomial exacta (0,995)^200=0,367). (4) suma de dos Poisson: Po(0,4)+Po(0,8)=Po(1,2), Pr(Z>=2)=0,338. (5) límites sigma de la gaussiana: 2 Phi(n)-1 = 68,3/95,4/99,7 % (independientes de mu, sigma). Gráfico de barras de Po(2) y figura de los límites sigma de la gaussiana con CeTZ (añadidos por el editor). Sin correcciones (los veintidós resultados son correctos, con Python/scipy). Confianza alta",
