     "html": "<strong>Enunciado (en inglés):</strong> «In the UK National Lottery each participant chooses six different numbers between 1 and 49. Six winning balls are drawn. Find the probabilities that a participant chooses <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>1</mn><mo>,</mo><mi>…</mi><mo>,</mo><mn>6</mn></mrow></math> winning numbers correctly.»"
