     "html": "La suma es uno: <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>44</mn><mspace width=\"0.222em\"></mspace><mo>+</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>41</mn><mspace width=\"0.222em\"></mspace><mo>+</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>13</mn><mspace width=\"0.222em\"></mspace><mo>+</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>02</mn><mspace width=\"0.222em\"></mspace><mo>+</mo><mi>O</mi><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msup><mn>10</mn><mrow><mi>−</mi><mn>3</mn></mrow></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mn>1</mn></mrow></math> (el autor lo comprueba sumando los términos principales y acotando el resto)."
