     "mota": "testua",
     "html": "<strong>Enunciado (en inglés):</strong> «A person receives on average one e-mail per half-hour interval... Find the probabilities that in any hour <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>1</mn><mo>,</mo><mi>…</mi><mo>,</mo><mn>5</mn></mrow></math> messages are received.»"
