     "html": "<strong>Enunciado (en inglés):</strong> «Sawmill A produces boards whose lengths are Gaussian with mean <math display=\"inline\"><mn>209.4</mn></math> cm and standard deviation <math display=\"inline\"><mn>5.0</mn></math> cm. A board is rejected if shorter than <math display=\"inline\"><mn>200</mn></math> cm. Show that <math display=\"inline\"><mrow><mn>3</mn><mi>%</mi></mrow></math> are rejected. Sawmill B has the same standard deviation but mean <math display=\"inline\"><mn>210.1</mn></math> cm. Find the proportion rejected if boards are drawn from A and B in the ratio <math display=\"inline\"><mrow><mn>3</mn><mo>:</mo><mn>1</mn></mrow></math>.»"
