       "html": "El papel escribe <math display=\"inline\"><mrow><mn>1</mn><mo>−</mo><mi mathvariant=\"normal\">Φ</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>1</mn><mo>,</mo><mn>33</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math>. Lo correcto es <math display=\"inline\"><mrow><mi mathvariant=\"normal\">Φ</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>1</mn><mo>,</mo><mn>88</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math>: (i) la línea anterior da <math display=\"inline\"><mrow><mi mathvariant=\"normal\">Φ</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>−</mi><mn>1</mn><mo>,</mo><mn>88</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math> y se aplica <math display=\"inline\"><mrow><mi mathvariant=\"normal\">Φ</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>−</mi><mi>z</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mn>1</mn><mo>−</mo><mi mathvariant=\"normal\">Φ</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>z</mi><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math>, por tanto el argumento debe ser <math display=\"inline\"><mrow><mn>1</mn><mo>,</mo><mn>88</mn></mrow></math>; (ii) el valor que escribe después, <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>9699</mn></mrow></math>, es <strong>exactamente</strong> <math display=\"inline\"><mrow><mi mathvariant=\"normal\">Φ</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>1</mn><mo>,</mo><mn>88</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math> (sería <math display=\"inline\"><mrow><mi mathvariant=\"normal\">Φ</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>1</mn><mo>,</mo><mn>33</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>9082</mn></mrow></math>). El autor leyó bien la tabla; el fallo está solo en el dígito escrito."
