     "html": "Siendo <math display=\"inline\"><mrow><mi>X</mi><mo>∼</mo><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> Bin</mtext></mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>200</mn><mo>;</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>1</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math>, <math display=\"inline\"><mrow><mi>E</mi><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>X</mi><mo stretchy=\"false\" form=\"postfix\">]</mo><mo>=</mo><mi>n</mi><mi>p</mi><mo>=</mo><mn>20</mn></mrow></math> y <math display=\"inline\"><mrow><mi>V</mi><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>X</mi><mo stretchy=\"false\" form=\"postfix\">]</mo><mo>=</mo><mi>n</mi><mi>p</mi><mi>q</mi><mo>=</mo><mn>200</mn><mo>⋅</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>1</mn><mspace width=\"0.222em\"></mspace><mo>⋅</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>9</mn><mspace width=\"0.222em\"></mspace><mo>=</mo><mn>18</mn></mrow></math>. Como <math display=\"inline\"><mi>n</mi></math> es grande, <math display=\"inline\"><mrow><mi>X</mi><mo>∼</mo><mi>N</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>20</mn><mo>;</mo><mn>18</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math> puede aproximarse. Con <strong>corrección de continuidad</strong> (usando <math display=\"inline\"><mrow><mn>15</mn><mo>,</mo><mn>5</mn></mrow></math> para «más de <math display=\"inline\"><mn>15</mn></math>»): <math display=\"block\"><mrow><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> Pr</mtext></mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>X</mi><mo>&gt;</mo><mspace width=\"0.222em\"></mspace><mn>15</mn><mo>,</mo><mn>5</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> Pr</mtext></mrow><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mi>Z</mi><mo>&gt;</mo><mfrac><mrow><mn>15</mn><mo>,</mo><mn>5</mn><mspace width=\"0.222em\"></mspace><mo>−</mo><mn>20</mn></mrow><msqrt><mn>18</mn></msqrt></mfrac><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> Pr</mtext></mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>Z</mi><mo>&gt;</mo><mi>−</mi><mn>1</mn><mo>,</mo><mn>06</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mi mathvariant=\"normal\">Φ</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>1</mn><mo>,</mo><mn>06</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>86</mn><mi>.</mi></mrow></math>"
