     "mota": "kutxa",
     "kolorea": "laranja",
     "titulua": null,
     "blokeak": [
      {
       "mota": "testua",
       "html": "<math display=\"block\"><mrow><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> Corr</mtext></mrow><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>X</mi><mo>,</mo><mi>Y</mi><mo stretchy=\"false\" form=\"postfix\">]</mo><mo>=</mo><mfrac><mrow><mtext mathvariant=\"normal\">Cov</mtext><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>X</mi><mo>,</mo><mi>Y</mi><mo stretchy=\"false\" form=\"postfix\">]</mo></mrow><mrow><msub><mi>σ</mi><mi>x</mi></msub><msub><mi>σ</mi><mi>y</mi></msub></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>3660</mn><mi>/</mi><mn>169</mn></mrow><msqrt><mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>480</mn><mi>/</mi><mn>169</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>28824</mn><mi>/</mi><mn>169</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></msqrt></mfrac><mo>=</mo><mfrac><mn>3660</mn><msqrt><mrow><mn>480</mn><mo>⋅</mo><mn>28824</mn></mrow></msqrt></mfrac><mo>≈</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>984</mn><mi>.</mi></mrow></math>"
      }
     ]
