     "html": "Es una correlación positiva fuerte, como se esperaba: <math display=\"inline\"><mrow><mi>Y</mi><mo>=</mo><msup><mi>X</mi><mn>2</mn></msup></mrow></math> es monótona creciente en el rango de valores del dado (positivos), pero no lineal; por eso la correlación es alta pero no exactamente <math display=\"inline\"><mn>1</mn></math>."
