       "html": "<math display=\"block\"><mrow><mi>ρ</mi><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mtable><mtr><mtd columnalign=\"center\" style=\"text-align: center\"><mn>1</mn></mtd><mtd columnalign=\"center\" style=\"text-align: center\"><mn>0</mn></mtd><mtd columnalign=\"center\" style=\"text-align: center\"><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>58</mn></mtd><mtd columnalign=\"center\" style=\"text-align: center\"><mspace width=\"0.222em\"></mspace><mo>−</mo><mn>0</mn><mo>,</mo><mn>21</mn></mtd></mtr><mtr><mtd columnalign=\"center\" style=\"text-align: center\"><mn>0</mn></mtd><mtd columnalign=\"center\" style=\"text-align: center\"><mn>1</mn></mtd><mtd columnalign=\"center\" style=\"text-align: center\"><mn>0</mn></mtd><mtd columnalign=\"center\" style=\"text-align: center\"><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>6</mn></mtd></mtr><mtr><mtd columnalign=\"center\" style=\"text-align: center\"><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>58</mn></mtd><mtd columnalign=\"center\" style=\"text-align: center\"><mn>0</mn></mtd><mtd columnalign=\"center\" style=\"text-align: center\"><mn>1</mn></mtd><mtd columnalign=\"center\" style=\"text-align: center\"><mspace width=\"0.222em\"></mspace><mo>−</mo><mn>0</mn><mo>,</mo><mn>36</mn></mtd></mtr><mtr><mtd columnalign=\"center\" style=\"text-align: center\"><mspace width=\"0.222em\"></mspace><mo>−</mo><mn>0</mn><mo>,</mo><mn>21</mn></mtd><mtd columnalign=\"center\" style=\"text-align: center\"><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>6</mn></mtd><mtd columnalign=\"center\" style=\"text-align: center\"><mspace width=\"0.222em\"></mspace><mo>−</mo><mn>0</mn><mo>,</mo><mn>36</mn></mtd><mtd columnalign=\"center\" style=\"text-align: center\"><mn>1</mn></mtd></mtr></mtable><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mi>.</mi></mrow></math>"
