        "<strong>Reverificado (Python, con fracciones y contando la baraja de 52 cartas):</strong> los treinta resultados son correctos. Dado: <math display=\"inline\"><mrow><mi>E</mi><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><msup><mi>X</mi><mn>3</mn></msup><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mo>=</mo><mn>101</mn></mrow></math> (entero), <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Cov</mtext><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>X</mi><mo>,</mo><mi>Y</mi><mo stretchy=\"false\" form=\"postfix\">]</mo><mo>=</mo><mn>3660</mn><mi>/</mi><mn>169</mn></mrow></math>, <math display=\"inline\"><mrow><msubsup><mi>σ</mi><mi>y</mi><mn>2</mn></msubsup><mo>=</mo><mn>28824</mn><mi>/</mi><mn>169</mn></mrow></math> (numerador <math display=\"inline\"><mn>187356</mn></math>, comprobado uno a uno), <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Corr</mtext><mo stretchy=\"false\" form=\"prefix\">[</mo><mi>X</mi><mo>,</mo><mi>Y</mi><mo stretchy=\"false\" form=\"postfix\">]</mo><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>984</mn></mrow></math>. Cartas: medias (<math display=\"inline\"><mrow><mn>1</mn><mi>/</mi><mn>2</mn></mrow></math>, <math display=\"inline\"><mrow><mn>16</mn><mi>/</mi><mn>13</mn></mrow></math>, <math display=\"inline\"><mrow><mn>1</mn><mi>/</mi><mn>2</mn></mrow></math>, <math display=\"inline\"><mrow><mn>3</mn><mi>/</mi><mn>13</mn></mrow></math>), varianzas (<math display=\"inline\"><mrow><mn>3</mn><mi>/</mi><mn>4</mn></mrow></math>, <math display=\"inline\"><mrow><mn>472</mn><mi>/</mi><mn>169</mn></mrow></math>, <math display=\"inline\"><mrow><mn>1</mn><mi>/</mi><mn>4</mn></mrow></math>, <math display=\"inline\"><mrow><mn>69</mn><mi>/</mi><mn>169</mn></mrow></math>), seis covarianzas y cuatro correlaciones no nulas (<math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>577</mn></mrow></math>, <math display=\"inline\"><mrow><mi>−</mi><mn>0</mn><mo>,</mo><mn>209</mn></mrow></math>, <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>598</mn></mrow></math>, <math display=\"inline\"><mrow><mi>−</mi><mn>0</mn><mo>,</mo><mn>361</mn></mrow></math>) coinciden. (No está en el corpus EDF; verificado con Python.)",
