     "mota": "testua",
     "html": "Hoja doble 16-17 del cuaderno amarillo CAx: un único problema en tres apartados. Doce alumnos de una clase de prácticas van al almacén a coger componentes, pero el profesor se olvida de decir cuántos traer de cada tipo. Hay tres tipos (A, B y C), en gran cantidad y en proporciones <math display=\"inline\"><mrow><mn>20</mn><mi>%</mi></mrow></math>, <math display=\"inline\"><mrow><mn>30</mn><mi>%</mi></mrow></math> y <math display=\"inline\"><mrow><mn>50</mn><mi>%</mi></mrow></math>, y cada alumno coge uno <strong>al azar</strong>. Para montar un experimento se necesitan un A, un B y <strong>dos</strong> C. Sea <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Pr</mtext><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>N</mi><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math> la probabilidad de poder montar al menos <math display=\"inline\"><mi>N</mi></math> experimentos."
