     "mota": "ingurunea",
     "izena": "Observación",
     "kolorea": "grisa",
     "etzana": false,
     "titulua": "La clave de la cuarta cifra decimal: <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>9144</mn></mrow></math> o <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>9145</mn></mrow></math>",
     "blokeak": [
      {
       "mota": "testua",
       "html": "El enunciado pide <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Pr</mtext><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>1</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>9145</mn></mrow></math>, pero el manuscrito obtiene <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>9144</mn></mrow></math>. La diferencia <strong>no es un error del autor</strong>: los términos de intersección descartados, precisamente por ser «del orden de <math display=\"inline\"><msup><mn>10</mn><mrow><mi>−</mi><mn>4</mn></mrow></msup></math>», son los que deciden la cuarta cifra decimal. El principal es <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Pr</mtext><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msub><mi>A</mi><mn>1</mn></msub><mo>∩</mo><msub><mi>A</mi><mn>2</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>0</mn><mo>,</mo><mn>5</mn><msup><mo stretchy=\"false\" form=\"postfix\">)</mo><mn>12</mn></msup><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>2</mn><mo>,</mo><mn>44</mn><mspace width=\"0.222em\"></mspace><mo>⋅</mo><msup><mn>10</mn><mrow><mi>−</mi><mn>4</mn></mrow></msup></mrow></math> (si <math display=\"inline\"><mrow><msub><mi>k</mi><mn>1</mn></msub><mo>=</mo><mn>0</mn></mrow></math> y <math display=\"inline\"><mrow><msub><mi>k</mi><mn>2</mn></msub><mo>=</mo><mn>0</mn></mrow></math> lo son, los doce son C). La suma de las seis intersecciones es <math display=\"inline\"><mrow><mn>2</mn><mo>,</mo><mn>55</mn><mspace width=\"0.222em\"></mspace><mo>⋅</mo><msup><mn>10</mn><mrow><mi>−</mi><mn>4</mn></mrow></msup></mrow></math>, por tanto: <math display=\"block\"><mrow><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> Pr</mtext></mrow><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msub><mi>A</mi><mn>1</mn></msub><mo>∪</mo><mi>…</mi><mo>∪</mo><msub><mi>A</mi><mn>4</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>085734</mn><mspace width=\"0.222em\"></mspace><mo>−</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>000255</mn><mspace width=\"0.222em\"></mspace><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>085479</mn><mo>,</mo><mspace width=\"1.0em\"></mspace><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> Pr</mtext></mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>1</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mn>1</mn><mo>−</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>085479</mn><mspace width=\"0.222em\"></mspace><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>91452</mn><mspace width=\"0.222em\"></mspace><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>9145</mn><mi>.</mi></mrow></math> El valor exacto (contando uno a uno toda la distribución multinomial de doce alumnos) es el mismo: <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Pr</mtext><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>1</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>9145208</mn></mrow></math>. Es decir, el desarrollo del autor es excelente y su estimación del orden de magnitud es correcta; lo que ocurre es que, aun siendo del orden de <math display=\"inline\"><msup><mn>10</mn><mrow><mi>−</mi><mn>4</mn></mrow></msup></math>, esos términos <strong>no son despreciables para la precisión que pide el enunciado</strong>. Teniéndolos en cuenta, sale el resultado exacto."
      }
     ]
