        "<strong>Reverificado (Python, con fracciones exactas y contando toda la distribución multinomial):</strong> todos los resultados son correctos. (a) <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Pr</mtext><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>3</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mn>6237</mn><mi>/</mi><mn>100000</mn><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>06237</mn></mrow></math> exactamente; <math display=\"inline\"><mrow><mn>12</mn><mi>!</mi><mi>/</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>3</mn><mi>!</mi><mn>3</mn><mi>!</mi><mn>6</mn><mi>!</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mn>18480</mn></mrow></math>; <math display=\"inline\"><mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>0</mn><mo>,</mo><mn>2</mn><msup><mo stretchy=\"false\" form=\"postfix\">)</mo><mn>3</mn></msup><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>0</mn><mo>,</mo><mn>3</mn><msup><mo stretchy=\"false\" form=\"postfix\">)</mo><mn>3</mn></msup><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>0</mn><mo>,</mo><mn>5</mn><msup><mo stretchy=\"false\" form=\"postfix\">)</mo><mn>6</mn></msup><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>3</mn><mo>,</mo><mn>375</mn><mspace width=\"0.222em\"></mspace><mo>⋅</mo><msup><mn>10</mn><mrow><mi>−</mi><mn>6</mn></mrow></msup></mrow></math>. (b) <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Pr</mtext><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>2</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>5829</mn></mrow></math>, y la forma <math display=\"inline\"><mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>0.5</mn><msup><mo stretchy=\"false\" form=\"postfix\">)</mo><mn>12</mn></msup><mo>∑</mo><mi>…</mi></mrow></math> (límites <math display=\"inline\"><mrow><mi>i</mi><mo>=</mo><mn>2</mn><mi>.</mi><mn>.6</mn></mrow></math>, <math display=\"inline\"><mrow><mi>j</mi><mo>=</mo><mn>2</mn><mi>.</mi><mn>.8</mn><mo>−</mo><mi>i</mi></mrow></math>) coincide <strong>exactamente</strong> con la enumeración. (c) los cuatro individuales (<math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>068719</mn></mrow></math>, <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>013841</mn></mrow></math>, <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>000244</mn></mrow></math>, <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>002930</mn></mrow></math>), suma <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>085734</mn></mrow></math>. (No está en el corpus EDF; verificado con Python.)",
        "<strong>Sin correcciones:</strong> todo el desarrollo es correcto. La única discrepancia en la cuarta cifra decimal <strong>no es un error</strong>, sino la consecuencia esperable de la aproximación que declara el propio autor (nota anterior).",
        "<strong>⭐⭐ Hallazgo (cuarta cifra decimal):</strong> calculadas las intersecciones, <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Pr</mtext><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>1</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>91452</mn><mspace width=\"0.222em\"></mspace><mo>=</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>9145</mn></mrow></math>, lo que pide el enunciado. El principal es <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Pr</mtext><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msub><mi>A</mi><mn>1</mn></msub><mo>∩</mo><msub><mi>A</mi><mn>2</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>0</mn><mo>,</mo><mn>5</mn><msup><mo stretchy=\"false\" form=\"postfix\">)</mo><mn>12</mn></msup></mrow></math>; la suma de todas las intersecciones <math display=\"inline\"><mrow><mn>2</mn><mo>,</mo><mn>55</mn><mspace width=\"0.222em\"></mspace><mo>⋅</mo><msup><mn>10</mn><mrow><mi>−</mi><mn>4</mn></mrow></msup></mrow></math>. La enumeración exacta lo confirma: <math display=\"inline\"><mrow><mn>0</mn><mo>,</mo><mn>9145208</mn></mrow></math>.",
        "<strong>Figura (añadida por el editor):</strong> región de <math display=\"inline\"><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msub><mi>k</mi><mn>1</mn></msub><mo>,</mo><msub><mi>k</mi><mn>2</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></math> puntos de la suma doble de <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Pr</mtext><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>2</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math> (15 puntos, triángulo <math display=\"inline\"><mrow><msub><mi>k</mi><mn>1</mn></msub><mo>+</mo><msub><mi>k</mi><mn>2</mn></msub><mo>≤</mo><mn>8</mn></mrow></math>). El manuscrito no tiene dibujo; la figura sirve para visualizar los límites de la suma doble.",
        "<strong>No se toca (dudas):</strong> el índice superior de la segunda combinación de (b) está escrito pequeño (es <math display=\"inline\"><mrow><mn>12</mn><mo>−</mo><msub><mi>k</mi><mn>1</mn></msub></mrow></math>, deducido); el factor <math display=\"inline\"><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>12</mn><mo>−</mo><msub><mi>k</mi><mn>1</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mi>!</mi><mi>/</mi><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>12</mn><mo>−</mo><msub><mi>k</mi><mn>1</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mi>!</mi></mrow></math> aparece como recordatorio; <math display=\"inline\"><mrow><msub><mi>A</mi><mn>1</mn></msub><mo>=</mo><msub><mi>k</mi><mn>1</mn></msub><mo>=</mo><mn>0</mn></mrow></math> con dos signos igual («<math display=\"inline\"><msub><mi>A</mi><mn>1</mn></msub></math> es el suceso <math display=\"inline\"><mrow><msub><mi>k</mi><mn>1</mn></msub><mo>=</mo><mn>0</mn></mrow></math>»). Todo se deja tal cual.",
