     "xehetasuna": "CAx, página 31 (unidad 0018, hoja suelta; #CAxp31): combinatoria — variaciones y combinaciones. ⭐⭐ TERCERA LENGUA DEL CUADERNO: la hoja está íntegramente en CASTELLANO (hasta ahora inglés y euskera). Regla del perfil: TRES lenguas según el material, imagen por imagen. El tema vuelve de las EDP a la COMBINATORIA (base de la probabilidad 1-21). Cuatro definiciones: V_(n,m)=n!/(n-m)!, C_(n,m)=binom(n,m), VR_(n,m)=n^m, CR_(n,m)=binom(n+m-1,m). ⭐⭐ Los cuatro casos son UN SOLO PROBLEMA (3 premios a 10 alumnos) en dos ejes (orden x repetición): V_(10,3)=720, C_(10,3)=120, VR_(10,3)=1000, CR_(10,3)=220. Cinco resultados correctos (Python + fuerza bruta con itertools). Las listas del margen justifican a mano la división por m! (C=V/m!). Dos tablas (clasificación + instanciación). Sin correcciones. Enunciados citados en castellano, definiciones en castellano. Confianza alta",
